/* only the two properties that should move get a transition */
.card {
  transition-property: transform, box-shadow;
}

.card:hover {
  transform: translateY(-4px);
  box-shadow: 0 10px 24px rgb(15 23 42 / 0.16);
}

/* the padding change below stays instant on purpose */
.card.is-large {
  padding: 28px;
}

.quick {
  transition-duration: 120ms;
}

.panel {
  transition-duration: 400ms;
}

/* several properties, one duration each, paired by position */
.mixed {
  transition-property: opacity, transform;
  transition-duration: 150ms, 300ms;
}

.fade {
  transition: opacity 200ms ease-out;
}

/* overshoot: y values may leave the 0 to 1 range */
.pop {
  transition: transform 220ms cubic-bezier(0.34, 1.56, 0.64, 1);
}

/* quantised time, one jump per tick */
.ticks {
  transition: transform 1s steps(12, end);
}

.tooltip {
  opacity: 0;
  transition: opacity 140ms ease;
}

/* entering waits a moment, leaving is immediate */
.trigger:hover .tooltip {
  opacity: 1;
  transition-delay: 150ms;
}

/* -100ms of a 400ms transition begins a quarter of the way in */
.warm-start {
  transition: transform 400ms ease -100ms;
}

/* duration 240ms, delay 0s */
.card {
  transition: transform 240ms ease-out 0s, box-shadow 240ms ease-out 0s;
}

/* wrong order: waits 240ms, then runs in 60ms */
.broken {
  transition: opacity 240ms 60ms ease;
}

/* centre a tooltip that was placed with left: 50% */
.tooltip {
  position: absolute;
  left: 50%;
  bottom: calc(100% + 8px);
  transform: translate(-50%, 4px);
}

.lift {
  transform: translateY(-6px);
}

/* zoom inside a clipped frame */
.frame {
  overflow: hidden;
}

.frame img {
  display: block;
  transition: transform 400ms ease-out;
}

.frame:hover img {
  transform: scale(1.06);
}

/* press feedback */
.key:active {
  transform: scale(0.98);
}

/* a chevron built from two borders */
.chevron {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-right: 2px solid currentColor;
  border-bottom: 2px solid currentColor;
  transform: rotate(45deg);
  transition: transform 160ms ease;
}

[aria-expanded="true"] .chevron {
  transform: rotate(-135deg);
}

.band {
  padding: 48px 20px;
  background-color: #24518f;
  color: #ffffff;
  transform: skewY(-3deg);
}

/* opposite angle puts the text upright again */
.band__inner {
  transform: skewY(3deg);
}

/* move along the page axis, then spin in place */
.after-translate {
  transform: translateX(100px) rotate(45deg);
}

/* spin first, then move along the rotated axis */
.after-rotate {
  transform: rotate(45deg) translateX(100px);
}

/* both ends share one function list, so interpolation is smooth */
.panel {
  transform: translateY(0) scale(1);
  transition: transform 220ms ease-out;
}

.panel.is-hidden {
  transform: translateY(12px) scale(0.98);
}

/* grow out of the left edge */
.panel {
  transform: scaleX(0);
  transform-origin: left center;
  transition: transform 220ms ease-out;
}

.panel.open {
  transform: scaleX(1);
}

/* a clock hand hinged at its base */
.hand {
  transform-origin: 50% 100%;
  transform: rotate(90deg);
}

/* one shared stage for all children */
.stage {
  perspective: 900px;
  perspective-origin: 50% 50%;
}

.card {
  transform: rotateY(25deg);
}

/* per element vanishing point, as the first function */
.lonely {
  transform: perspective(900px) rotateY(25deg);
}

.flip {
  perspective: 1000px;
}

.flip__inner {
  position: relative;
  transform-style: preserve-3d;
  transition: transform 500ms ease;
}

.flip:hover .flip__inner {
  transform: rotateY(180deg);
}

/* without preserve-3d the two faces land on one plane */

.flip__face {
  position: absolute;
  inset: 0;
  backface-visibility: hidden;
}

/* the back starts turned around */
.flip__face--back {
  transform: rotateY(180deg);
  background-color: #24518f;
  color: #ffffff;
}

@keyframes slide-up {
  from {
    opacity: 0;
    transform: translateY(14px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.card {
  animation: slide-up 420ms ease-out both;
}

.hero {
  animation-name: slide-up;
  animation-duration: 450ms;
}

/* several animations at once, paired by position */
.status {
  animation-name: fade-in, pulse;
  animation-duration: 300ms, 2s;
  animation-iteration-count: 1, infinite;
}

@keyframes spin {
  to { transform: rotate(1turn); }
}

.spinner {
  animation-name: spin;
  animation-duration: 800ms;
  animation-timing-function: linear;
  animation-iteration-count: infinite;
}

@keyframes drop {
  0% {
    transform: translateY(-40px);
    animation-timing-function: ease-in;   /* accelerate down */
  }
  70% {
    transform: translateY(0);
    animation-timing-function: ease-out;  /* settle on landing */
  }
  100% {
    transform: translateY(0);
  }
}

.ball {
  animation: drop 700ms both;
}

.blink {
  animation: blink 900ms steps(1, end) infinite;
}

.once {
  animation: fade-in 400ms ease 1 both;
}

/* half of the second pass, then it stops */
.halfway {
  animation: slide 1s ease 1.5 both;
}

/* one out and back, not two passes forward */
.breathe {
  animation: breathe 2s ease-in-out infinite alternate;
}

/* same frames, counter clockwise */
.counter-spin {
  animation: spin 800ms linear infinite reverse;
}

/* hold the first frame during the 120ms delay, keep the last frame after the end */
.enter {
  animation: slide-up 450ms ease-out 120ms 1 normal both;
}

/* final state declared outside the keyframes as a safety net */
.enter {
  opacity: 1;
  transform: translateY(0);
}

.ticker__track {
  animation: ticker 16s linear infinite;
}

/* let people stop a moving strip by hovering or tabbing to it */
.ticker:hover .ticker__track,
.ticker:focus-within .ticker__track {
  animation-play-state: paused;
}

/* name, duration, timing, delay, iterations, direction, fill */
.hero {
  animation: panel-in 460ms cubic-bezier(0.22, 0.61, 0.36, 1) 80ms 1 normal both;
}

/* four layers at once */
.card {
  animation: slide-up 420ms ease-out both, glow 2s ease-in-out infinite;
}

/* one element, one hint, only while it is about to move */
.drawer {
  will-change: transform;
  transition: transform 260ms ease-out;
}

/* remove the hint once the movement is over */
.drawer.is-settled {
  will-change: auto;
}

@media (prefers-reduced-motion: reduce) {
  .card,
  .panel {
    transition-duration: 0.01ms;
    animation: none;
  }

  .card:hover {
    transform: none;           /* keep colour and border feedback */
  }

  .ticker__track {
    animation: none;           /* static strip instead of a loop */
  }

  .loader {
    animation: pulse-opacity 1.6s ease-in-out infinite;
  }
}
